"""
generate_dashboard.py
----------------------
Regenerate the Retail Sales Performance Dashboard (HTML) -- Handset,
Accessories, Attach Rate, Entry Model, AND Sheep pages -- from an
updated Refresh_TSM.xlsx export (and optionally an updated Sheep_Report
export and/or shop master list).

USAGE:
    python generate_dashboard.py
    python generate_dashboard.py path/to/Refresh_TSM.xlsx
    python generate_dashboard.py path/to/Refresh_TSM.xlsx path/to/output.html
    python generate_dashboard.py path/to/Refresh_TSM.xlsx path/to/output.html path/to/List_XX_Shop.xlsx
    python generate_dashboard.py path/to/Refresh_TSM.xlsx path/to/output.html path/to/List_XX_Shop.xlsx path/to/Sheep_Report.xlsx

    (Pass an empty string "" for the shop-list argument if you want to
    skip it but still supply a custom Sheep report path, e.g.:
    python generate_dashboard.py Refresh_TSM.xlsx Handset_Sales_Dashboard.html "" Sheep_Report.xlsx)

Requirements:
    pip install pandas openpyxl

What it does:
    1. Reads the "TSM" sheet -- builds the Handset and Accessories pages
       covering ALL shop types (Matching, Non Matching, Hall, COCO). Each
       page has independent filters (Region / Shop Type / Area
       multi-select / Date / Shop Name search), KPIs, Daily Trend and
       Regional Performance charts (both with on-chart data labels),
       Area Drill-down, Shop Leaderboard (all shops incl. zero-sale),
       Brand Market Share (bar), Brand Distribution by Qty and by Price
       (doughnut charts with % data labels), and Top Models/Products
       charts.
    2. Reads the Sheep_Report.xlsx "Export" sheet (SHOP_TYPE values like
       "True Shop Matching" are normalised to "Matching" to match the
       TSM sheet's convention) -- builds a Sheep page with the EXACT SAME
       layout/behaviour as the Accessories page. If no Sheep report file
       is found, this page is built with 0 rows (page still renders, all
       values show 0) rather than failing the whole script.
    3. Builds the Attach Rate page: combines Handset + Accessories +
       Sheep per shop/date. %Attach Rate = (Accessories Qty + Sheep Qty)
       / Handset Qty. Summary banner, daily attach-rate trend + regional
       attach-rate charts (with data labels), area drill-down, and a shop
       leaderboard (Handset Qty / Acc Qty / Sheep Qty / Attach Rate,
       sortable) with CSV export.
    4. Builds the Entry Model page: tracks a fixed set of entry-level
       handset models (see ENTRY_MODEL_TARGETS below) against their
       monthly unit targets -- Actual vs Target, %Achieve, and pace vs.
       time elapsed in the month. Only a Date filter applies. CSV export.
       *** EDIT ENTRY_MODEL_TARGETS / ENTRY_MODEL_MONTH_DAYS /
       ENTRY_MODEL_MONTH_LABEL BELOW WHEN THE TARGET MONTH OR MODEL LIST
       CHANGES. ***
    5. Shop master list (SHOP CODE / SHOP NAME / TYPE SHOP / AREA /
       REGION), used by every page's Shop Leaderboard so shops with zero
       activity are never hidden. By default this is DERIVED AUTOMATICALLY
       from the shops appearing in the TSM sheet itself. Pass a
       List_XX_Shop.xlsx as the 3rd argument only if you have an
       authoritative master list that includes shops with absolutely zero
       transactions of any kind.
    6. All filters, KPIs, and charts recompute automatically in the
       browser -- no manual editing needed after this script runs.
"""
import os
import sys
import json
import pandas as pd

TEMPLATE = '<!DOCTYPE html>\n<html lang="th">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Handset Sales Performance — TSM Dashboard</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&display=swap" rel="stylesheet">\n<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/chartjs-plugin-datalabels/2.2.0/chartjs-plugin-datalabels.min.js"></script>\n<style>\n__CSS__\n</style>\n</head>\n<body>\n__BODY__\n<script>\nconst HANDSET_DATA = __HANDSET_DATA__;\nconst ACCESSORIES_DATA = __ACCESSORIES_DATA__;\nconst SHEEP_DATA = __SHEEP_DATA__;\nconst SHOPS_MASTER = __SHOPS__;\nconst ENTRY_MODEL_TARGETS = __ENTRY_MODEL_TARGETS__;\nconst ENTRY_MODEL_MONTH_DAYS = __ENTRY_MODEL_MONTH_DAYS__;\nconst ENTRY_MODEL_MONTH_LABEL = __ENTRY_MODEL_MONTH_LABEL__;\n__JS__\n</script>\n</body>\n</html>\n'
CSS = ":root{\n  --bg:#F3F4F8;\n  --surface:#FFFFFF;\n  --ink:#0E1526;\n  --ink-soft:#4B5468;\n  --muted:#8890A0;\n  --navy:#101B3D;\n  --navy-2:#182752;\n  --line:#E4E7EF;\n  --accent:#E8483C;\n  --accent-soft:#FCE7E5;\n  --teal:#1E9E86;\n  --teal-soft:#DFF5EF;\n  --amber:#D98A2B;\n  --amber-soft:#FBEEDD;\n  --radius:14px;\n  --shadow:0 1px 2px rgba(16,27,61,0.04), 0 8px 24px -12px rgba(16,27,61,0.12);\n}\n*{box-sizing:border-box;}\nhtml,body{margin:0;padding:0;}\nbody{\n  background:var(--bg);\n  color:var(--ink);\n  font-family:'Inter',-apple-system,BlinkMacSystemFont,sans-serif;\n  -webkit-font-smoothing:antialiased;\n}\n.num{font-family:'IBM Plex Mono',monospace;font-variant-numeric:tabular-nums;}\n\n/* ===== Header ===== */\n.topbar{\n  background:linear-gradient(135deg,var(--navy) 0%, var(--navy-2) 100%);\n  color:#fff;\n  padding:26px 36px 22px;\n}\n.topbar-inner{max-width:1360px;margin:0 auto;display:flex;justify-content:space-between;align-items:flex-end;gap:24px;flex-wrap:wrap;}\n.brand-eyebrow{\n  font-family:'IBM Plex Mono',monospace;\n  font-size:11px;letter-spacing:.14em;text-transform:uppercase;\n  color:#F0A79E;margin:0 0 8px;\n}\n.brand-title{\n  font-family:'Space Grotesk',sans-serif;\n  font-size:30px;font-weight:700;margin:0;letter-spacing:-0.01em;\n}\n.brand-sub{color:#AEB6D6;font-size:13px;margin-top:6px;}\n\n/* ===== Layout ===== */\n.wrap{max-width:1360px;margin:0 auto;padding:24px 36px 60px;}\n\n/* ===== Filter bar ===== */\n.filterbar{\n  background:var(--surface);\n  border:1px solid var(--line);\n  border-radius:var(--radius);\n  box-shadow:var(--shadow);\n  padding:18px 22px;\n  position:relative;\n  z-index:5;\n  display:flex;\n  gap:28px;\n  flex-wrap:wrap;\n  align-items:flex-start;\n}\n.filter-group{display:flex;flex-direction:column;gap:8px;}\n.filter-label{\n  font-size:10.5px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;\n  color:var(--muted);\n}\n.filter-label-hint{\n  font-size:10px; font-weight:500; letter-spacing:0; text-transform:none;\n  color:#B7BCC9; margin-left:2px;\n}\n.chip-row{display:flex;gap:7px;flex-wrap:wrap;max-width:640px;}\n#areaChips{max-width:900px;}\n.chip{\n  border:1px solid var(--line);\n  background:#fff;\n  color:var(--ink-soft);\n  font-size:12.5px;\n  font-weight:500;\n  padding:7px 13px;\n  border-radius:8px;\n  cursor:pointer;\n  transition:all .12s ease;\n  white-space:nowrap;\n}\n.chip:hover{border-color:var(--accent);color:var(--accent);}\n.chip.active{\n  background:var(--navy);\n  border-color:var(--navy);\n  color:#fff;\n}\n.chip.active.date{background:var(--teal);border-color:var(--teal);}\n.reset-btn{\n  margin-left:auto;\n  align-self:center;\n  background:none;\n  border:1px solid var(--line);\n  color:var(--ink-soft);\n  font-size:12.5px;font-weight:600;\n  padding:9px 16px;\n  border-radius:8px;\n  cursor:pointer;\n}\n.reset-btn:hover{border-color:var(--ink);color:var(--ink);}\n\n.export-btn{\n  background:var(--navy);\n  border:1px solid var(--navy);\n  color:#fff;\n  font-size:12.5px;font-weight:600;\n  padding:9px 16px;\n  border-radius:8px;\n  cursor:pointer;\n  white-space:nowrap;\n}\n.export-btn:hover{background:var(--navy-2);}\n\n.shop-search{\n  border:1px solid var(--line);\n  background:#fff;\n  color:var(--ink);\n  font-family:'Inter',sans-serif;\n  font-size:12.5px;\n  padding:8px 12px;\n  border-radius:8px;\n  width:220px;\n  outline:none;\n}\n.shop-search:focus{border-color:var(--navy);}\n.shop-search::placeholder{color:var(--muted);}\n\n/* ===== KPI cards ===== */\n.kpi-row{\n  display:grid;\n  grid-template-columns:repeat(4,1fr);\n  gap:16px;\n  margin-top:22px;\n}\n.kpi-card{\n  background:var(--surface);\n  border:1px solid var(--line);\n  border-radius:var(--radius);\n  padding:18px 20px;\n  box-shadow:var(--shadow);\n  border-top:3px solid var(--navy);\n}\n.kpi-card.c2{border-top-color:var(--accent);}\n.kpi-card.c3{border-top-color:var(--teal);}\n.kpi-card.c4{border-top-color:var(--amber);}\n.kpi-label{font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);}\n.kpi-value{\n  font-family:'Space Grotesk',sans-serif;\n  font-size:30px;font-weight:700;color:var(--ink);\n  margin-top:8px;\n}\n.kpi-unit{font-size:14px;color:var(--muted);font-weight:500;margin-left:4px;}\n\n/* ===== Section cards ===== */\n.grid-2{display:grid;grid-template-columns:1.35fr 1fr;gap:16px;margin-top:16px;}\n.grid-2b{display:grid;grid-template-columns:1fr 1.2fr;gap:16px;margin-top:16px;}\n.panel{\n  background:var(--surface);\n  border:1px solid var(--line);\n  border-radius:var(--radius);\n  box-shadow:var(--shadow);\n  padding:20px 22px 22px;\n}\n.panel-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px;flex-wrap:wrap;gap:6px;}\n.panel-title{\n  font-family:'Space Grotesk',sans-serif;\n  font-size:15px;font-weight:600;color:var(--ink);\n}\n.panel-hint{font-size:11.5px;color:var(--muted);}\n.chart-box{position:relative;height:260px;}\n.chart-box.tall{height:340px;}\n\n/* ===== Area bars (custom horizontal chart) ===== */\n.area-list{display:flex;flex-direction:column;gap:9px;margin-top:4px;}\n.area-row{display:grid;grid-template-columns:150px 1fr 82px;align-items:center;gap:10px;cursor:pointer;padding:4px 6px;border-radius:8px;}\n.area-row:hover{background:#F7F8FC;}\n.area-row.active{background:var(--accent-soft);}\n.area-name{font-size:12.5px;color:var(--ink-soft);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.area-row.active .area-name{color:var(--accent);font-weight:600;}\n.area-track{background:#EEF0F6;border-radius:6px;height:10px;overflow:hidden;}\n.area-fill{background:linear-gradient(90deg,var(--navy),var(--accent));height:100%;border-radius:6px;transition:width .25s ease;}\n.area-val{font-size:12px;text-align:right;color:var(--ink-soft);}\n\n/* ===== Leaderboard table ===== */\n.lb-scroll{max-height:560px; overflow-y:auto; border:1px solid var(--line); border-radius:10px;}\ntable.lb{width:100%;border-collapse:collapse;font-size:12.8px;}\ntable.lb th{\n  text-align:left;font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;\n  color:var(--muted);border-bottom:1px solid var(--line);padding:8px 10px;cursor:pointer;user-select:none;\n  position:sticky; top:0; background:var(--surface); z-index:2;\n}\ntable.lb th.num,table.lb td.num{text-align:right;}\ntable.lb th:hover{color:var(--ink);}\ntable.lb td{padding:9px 10px;border-bottom:1px solid #F0F1F6;color:var(--ink-soft);}\ntable.lb tr:hover td{background:#F9FAFC;}\ntable.lb tr.zero-row td{color:var(--muted);}\ntable.lb tr.zero-row .shop-name{color:var(--ink-soft); font-weight:500;}\ntable.lb tr.zero-row .rank-badge{background:#EEF0F6; color:var(--muted);}\n.rank-badge{\n  display:inline-flex;align-items:center;justify-content:center;\n  width:22px;height:22px;border-radius:6px;\n  font-size:11px;font-weight:700;color:#fff;background:var(--muted);\n}\n.rank-badge.r1{background:var(--accent);}\n.rank-badge.r2{background:var(--amber);}\n.rank-badge.r3{background:var(--teal);}\n.shop-name{color:var(--ink);font-weight:600;}\n.bar-cell{position:relative;}\n.bar-cell .track{position:absolute;left:10px;right:10px;bottom:2px;height:3px;background:#EEF0F6;border-radius:3px;}\n.bar-cell .fill{position:absolute;left:10px;bottom:2px;height:3px;background:var(--teal);border-radius:3px;}\n\nfooter{max-width:1360px;margin:0 auto;padding:0 36px 40px;color:var(--muted);font-size:11.5px;}\n\n/* ===== Section title row (report section breaks) ===== */\n.section-title-row{\n  display:flex; align-items:center; gap:14px;\n  margin:28px 0 4px;\n}\n.section-title-eyebrow{\n  font-family:'Space Grotesk',sans-serif;\n  font-size:13px; font-weight:700; letter-spacing:.04em;\n  color:var(--navy);\n  white-space:nowrap;\n}\n.section-title-row::after{\n  content:'';\n  flex:1;\n  height:1px;\n  background:var(--line);\n}\n\n/* ===== Model panel toggle ===== */\n.model-toggle{display:flex; gap:7px; margin-bottom:10px;}\n.model-toggle .chip{padding:5px 12px; font-size:11.5px;}\n\n/* ===== Tab bar (page switcher) ===== */\n.tabbar{display:flex; gap:8px;}\n.tab-btn{\n  background:rgba(255,255,255,0.08);\n  border:1px solid rgba(255,255,255,0.16);\n  color:#C9CFE6;\n  font-family:'Inter',sans-serif;\n  font-size:13px; font-weight:600;\n  padding:9px 18px;\n  border-radius:9px;\n  cursor:pointer;\n  transition:all .12s ease;\n}\n.tab-btn:hover{border-color:rgba(255,255,255,0.32); color:#fff;}\n.tab-btn.active{\n  background:#fff;\n  color:var(--navy);\n  border-color:#fff;\n}\n\n/* ===== Page show/hide ===== */\n.page{display:none;}\n.page.active{display:block;}\n\n/* ===== Scope line (per-page summary pill, sits above filter bar) ===== */\n.scope-line{margin:-18px 0 14px; position:relative; z-index:6;}\n.scope-line .scope-pill{\n  display:inline-block;\n  background:var(--surface);\n  border:1px solid var(--line);\n  border-radius:999px;\n  padding:7px 16px;\n  font-size:12.5px;\n  color:var(--ink-soft);\n  box-shadow:var(--shadow);\n}\n.scope-line .scope-pill b{color:var(--navy); font-family:'IBM Plex Mono',monospace;}\n\n@media (max-width:1000px){\n  .kpi-row{grid-template-columns:repeat(2,1fr);}\n  .grid-2,.grid-2b{grid-template-columns:1fr;}\n  .topbar,.wrap{padding-left:20px;padding-right:20px;}\n}\n\n/* ===== Trend Performance: Summary Banner ===== */\n.trend-banner{\n  background:var(--surface);\n  border:1px solid var(--line);\n  border-radius:var(--radius);\n  box-shadow:var(--shadow);\n  padding:22px 24px 24px;\n  margin-bottom:16px;\n}\n.trend-banner-top{display:flex; justify-content:space-between; align-items:baseline; margin-bottom:16px; flex-wrap:wrap; gap:8px;}\n.trend-banner-eyebrow{\n  font-family:'Space Grotesk',sans-serif; font-size:15px; font-weight:700; color:var(--navy);\n}\n.trend-dataof{font-size:12px; color:var(--muted); margin-left:12px;}\n.trend-summary-grid{display:grid; grid-template-columns:1.1fr 1fr; gap:24px; align-items:start;}\n\n.mom-kpi-row{display:flex; align-items:center; gap:14px; flex-wrap:wrap;}\n.mom-kpi-card{\n  background:#F8F9FC; border:1px solid var(--line); border-radius:10px;\n  padding:12px 18px; min-width:140px;\n}\n.mom-kpi-card.highlight{background:var(--teal-soft); border-color:#BFE7DC;}\n.mom-kpi-label{font-size:10.5px; font-weight:600; letter-spacing:.06em; text-transform:uppercase; color:var(--muted);}\n.mom-kpi-value{font-family:'Space Grotesk',sans-serif; font-size:22px; font-weight:700; color:var(--ink); margin-top:4px;}\n.mom-kpi-arrow{font-size:18px; color:var(--muted);}\n\n.tier-row{display:flex; gap:10px; flex-wrap:wrap; margin-top:18px;}\n.tier-badge{\n  border-radius:10px; padding:10px 16px; min-width:96px;\n  border:1px solid var(--line); background:#fff;\n}\n.tier-badge .tier-count{font-family:'Space Grotesk',sans-serif; font-size:20px; font-weight:700;}\n.tier-badge .tier-label{font-size:10.5px; font-weight:600; color:var(--ink-soft); margin-top:2px;}\n.tier-badge.tier-neg{background:#FDEDEC; border-color:#F6C6C0;}\n.tier-badge.tier-neg .tier-count{color:#C0392B;}\n.tier-badge.tier-low{background:#FEF6E7; border-color:#F7DFA5;}\n.tier-badge.tier-low .tier-count{color:#B7791F;}\n.tier-badge.tier-mid{background:#FFF9E0; border-color:#F2E6A0;}\n.tier-badge.tier-mid .tier-count{color:#9C7C0A;}\n.tier-badge.tier-high{background:#EAF7EE; border-color:#B8E4C6;}\n.tier-badge.tier-high .tier-count{color:#1E8449;}\n.tier-badge.tier-vhigh{background:#E3F3EC; border-color:#9CD9BC;}\n.tier-badge.tier-vhigh .tier-count{color:#137A4B;}\n\n.trend-summary-right .chart-box{height:220px; margin-top:6px;}\n\n/* ===== Trend table panel ===== */\n.trend-table-panel{padding-bottom:14px;}\n.trend-filterbar{display:flex; gap:14px; flex-wrap:wrap; align-items:flex-end; margin:4px 0 16px;}\n.dropdown{\n  border:1px solid var(--line); background:#fff; color:var(--ink);\n  font-family:'Inter',sans-serif; font-size:12.5px; padding:8px 10px;\n  border-radius:8px; min-width:150px; outline:none;\n}\n.dropdown:focus{border-color:var(--navy);}\n\n/* ===== Multi-select dropdown (checkbox panel) ===== */\n.msdd{position:relative; display:inline-block;}\n.msdd-btn{\n  border:1px solid var(--line); background:#fff; color:var(--ink);\n  font-family:'Inter',sans-serif; font-size:12.5px; padding:8px 12px;\n  border-radius:8px; min-width:150px; max-width:220px; text-align:left;\n  cursor:pointer; display:flex; justify-content:space-between; align-items:center; gap:8px;\n  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\n}\n.msdd-btn:hover{border-color:var(--navy);}\n.msdd-btn.has-selection{border-color:var(--navy); background:#F5F7FC; color:var(--navy); font-weight:600;}\n.msdd-panel{\n  display:none; position:absolute; top:calc(100% + 6px); left:0; z-index:30;\n  background:#fff; border:1px solid var(--line); border-radius:10px;\n  box-shadow:var(--shadow); width:250px; max-height:290px; overflow-y:auto; padding:8px;\n}\n.msdd-panel.open{display:block;}\n.msdd-actions{\n  display:flex; justify-content:space-between; align-items:center;\n  font-size:11px; color:var(--muted); padding:2px 6px 8px; margin-bottom:6px;\n  border-bottom:1px solid var(--line);\n}\n.msdd-actions a{color:var(--navy); cursor:pointer; font-weight:600;}\n.msdd-actions a:hover{text-decoration:underline;}\n.msdd-search{\n  width:100%; box-sizing:border-box; border:1px solid var(--line); border-radius:6px;\n  padding:6px 8px; font-size:12px; margin-bottom:6px; outline:none;\n}\n.msdd-search:focus{border-color:var(--navy);}\n.msdd-item{\n  display:flex; align-items:center; gap:8px; padding:6px 8px; border-radius:6px;\n  font-size:12.5px; color:var(--ink-soft); cursor:pointer;\n}\n.msdd-item:hover{background:#F3F6FB;}\n.msdd-item input{accent-color:var(--navy); cursor:pointer;}\n.msdd-empty{font-size:12px; color:var(--muted); padding:8px; text-align:center;}\n\n.mom-table-wrap{max-height:600px; overflow:auto; border:1px solid var(--line); border-radius:10px; position:relative;}\ntable.mom-table{border-collapse:separate; border-spacing:0; font-size:12px; width:max-content; min-width:100%;}\ntable.mom-table th, table.mom-table td{padding:8px 10px; border-bottom:1px solid #F0F1F6; white-space:nowrap;}\ntable.mom-table thead th{\n  position:sticky; top:0; z-index:3; background:var(--navy); color:#fff;\n  font-size:10px; font-weight:700; letter-spacing:.05em; text-transform:uppercase; text-align:right;\n  border-bottom:none;\n}\ntable.mom-table thead th.col-shop{text-align:left;}\ntable.mom-table th.col-shop, table.mom-table td.col-shop{\n  position:sticky; left:0; z-index:2; background:#fff;\n  text-align:left; min-width:220px; max-width:220px; white-space:normal;\n  box-shadow:2px 0 4px -2px rgba(16,27,61,0.12);\n}\ntable.mom-table thead th.col-shop{background:var(--navy); z-index:4;}\ntable.mom-table td{text-align:right; color:var(--ink-soft); font-family:'IBM Plex Mono',monospace; font-size:11.5px;}\ntable.mom-table td.col-meta{font-family:'Inter',sans-serif; color:var(--ink-soft); font-size:11.5px;}\ntable.mom-table tbody tr:nth-child(even) td{background:#FAFBFD;}\ntable.mom-table tbody tr:nth-child(even) td.col-shop{background:#FAFBFD;}\ntable.mom-table tbody tr:hover td{background:#F3F6FB;}\ntable.mom-table tbody tr:hover td.col-shop{background:#F3F6FB;}\ntable.mom-table td.col-highlight{font-weight:700; color:var(--ink); background:#F5F8FF;}\ntable.mom-table tbody tr:nth-child(even) td.col-highlight{background:#EFF3FC;}\ntable.mom-table td.col-mom{font-weight:700; border-radius:6px;}\ntable.mom-table td.col-trend{padding:4px 10px;}\n.spark-svg{display:block;}\n\n/* ===== Entry Model progress bars ===== */\n.em-progress-track{background:#EEF0F6; border-radius:6px; height:12px; width:100%; min-width:120px; overflow:hidden; position:relative;}\n.em-progress-fill{height:100%; border-radius:6px; transition:width .25s ease;}\n.em-achieve-cell{font-weight:700; border-radius:6px; padding:4px 8px; text-align:center;}\n"
